import{_ as t,l as r,o as a,c as i,v as o,p as s,x as d,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"RISC-V 整数指令","description":"","frontmatter":{"title":"RISC-V 整数指令","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-int-isa.md","filePath":"cs/riscv-int-isa.md","lastUpdated":1789023840000}'),h={name:"cs/riscv-int-isa.md"};function E(A,e,u,m,_,S){const c=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="risc-v-整数指令" tabindex="-1">RISC-V 整数指令 <a class="header-anchor" href="#risc-v-整数指令" aria-label="Permalink to &quot;RISC-V 整数指令&quot;">​</a></h1><div class="epigraph"><p>RV32I 用一套固定格式覆盖运算、访存、分支与跳转；每条指令的语义是对寄存器与内存的确定变换。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume I 整理</footer></div><p>上一课<a href="/cs/risc-cisc">RISC 与 CISC</a>钉死了字段布局。本课不重拼立即数位，也不从「什么是 RISC」的历史综述另起。缺口是：字段还没有<strong>语义</strong>。数据通路要对着具体指令接线：哪些读寄存器、是否访存、PC 如何更新。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>格式课给出 R/I/S/B/U/J。缺口是 RV32I 核心操作：<code>add</code>/<code>sub</code>/<code>and</code>/<code>or</code>/<code>xor</code>/<code>sll</code>/<code>slt</code> 等 R 型；立即数版本 <code>addi</code>、<code>lw</code> 的地址 <code>rs1+imm</code>、<code>sw</code> 的 S 型；<code>beq</code>/<code>bne</code>/<code>blt</code>/<code>bltu</code> 相对 PC 的偏移；<code>jal</code>/<code>jalr</code> 写返回地址；<code>lui</code>/<code>auipc</code> 建宽常数。<code>x0</code> 硬接 0，写它丢弃。</p><p>本课只钉整数用户级子集。CSR、特权、浮点、<code>fence</code> 的完整内存模型后置。</p><h3 id="addi-不是「把立即数当无符号」" tabindex="-1"><code>addi</code> 不是「把立即数当无符号」 <a class="header-anchor" href="#addi-不是「把立即数当无符号」" aria-label="Permalink to &quot;`addi` 不是「把立即数当无符号」&quot;">​</a></h3><p>12 位立即数符号扩展再加，与<a href="/cs/twos-complement">补码</a>一致。<code>sltiu</code> 把扩展后的值当无符号比。把所有 <code>*i</code> 当零扩展，负数立即数会错。移位量只取低 5 位（RV32）。</p><p><span class="marginnote">Patterson/Hennessy 第 2 章用 RV32I 当全书例子。官方手册是规范；本课按教材范围：够画单周期数据通路的那些指令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每类指令列：用哪些寄存器口、ALU 作什么、是否读/写内存、下一 PC 是 +4 还是 PC+offset 或 jalr 目标。分支比较用<a href="/cs/comparator-circuit">比较器</a>或 ALU 零/小于。加载宽度 <code>lw</code>/<code>lh</code>/<code>lb</code> 与符号扩展、零扩展要分开。</p>',11)),(a(),s(p,null,{default:d(()=>[n(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FMT%5B%22RISC-V%20%E6%A0%BC%E5%BC%8F%22%5D%20--%3E%20OP%5B%22%E8%BF%90%E7%AE%97%20%2F%20%E8%AE%BF%E5%AD%98%20%2F%20%E5%88%86%E6%94%AF%22%5D%0A%20%20OP%20--%3E%20SEM%5B%22%E5%AF%B9%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%E5%86%85%E5%AD%98%E7%9A%84%E5%8F%98%E6%8D%A2%22%5D%0A%20%20SEM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%E7%AB%AF%E5%8F%A3%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了语义，才能说「这条指令需要两个读口、一个写口、ALU、数据存储器」。没有的功能（整数除法在 M 扩展）本课不假装存在。伪指令 <code>li</code>、<code>mv</code> 是汇编器合成，硬件仍只看见真实编码。</p><p>对齐：<code>lw</code> 地址应 4 的倍数，否则异常——入口课再接。本课承认约束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲向量、不把 Linux syscall 编号当 ISA。RV64 只把寄存器与立即数加宽，本课以 32 位教学。压缩指令是同一语义的另一编码。</p><p>后课默认：谈到「一条整数指令」，语义在 RV32I 这张表上；硬件要提供 32×32 位寄存器与按语义接线的功能单元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RV32I 给出运算、访存、分支、跳转的确定语义。</li><li><code>x0</code> 为 0；立即数多数符号扩展。</li><li>伪指令不是额外硬件。寄存器堆下一课实现。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V ISA Manual, Vol. I。</li></ul>',8))])}const f=t(h,[["render",E]]);export{I as __pageData,f as default};
